for slug,(title,content) in PAGES.items():
 nav=''.join(f'<a href="{path}.html"'+(' class="active" aria-current="page"' if slug==path else '')+f'>{icon(ico)}<span>{label}</span></a>' for path,label,ico in NAV)
 side=''.join(f'<a href="{path}.html"'+(' class="active"' if slug==path else '')+f'><i></i><b>0{i+1}</b><span>{label}</span></a>' for i,(path,label) in enumerate([('index','Início'),('servicos','Serviços'),('diferenciais','Diferenciais'),('processo','Processo'),('avaliacoes','Avaliações'),('contato','Contato')]))
 html=f'''<!doctype html><html lang="pt-BR"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#041014"><title>{title} | TechCell</title><meta name="description" content="TechCell: assistência técnica especializada. Diagnóstico, reparos e tecnologia para seu celular. {title}."><link rel="icon" href="assets/favicon.svg" type="image/svg+xml"><link rel="preload" href="assets/orbitron.woff2" as="font" type="font/woff2" crossorigin><link rel="stylesheet" href="styles.css"><script src="app.js" defer></script></head><body class="{'home-page' if slug=='index' else 'inner-page'}" data-page="{slug}">
<a class="skip-link" href="#main">Pular para o conteúdo</a><div class="lab-world" aria-hidden="true"><div class="scene"></div><canvas id="lab-effects"></canvas><div class="scene-vignette"></div><div class="tube-reactor"><div class="reactor-ring"></div><div class="tube-fluid"></div><div class="reactor-orbit"></div><div class="reactor-core"><span data-brand-initial>E</span></div><div class="tube-scan"></div><span class="reactor-caption">ENERGY CORE</span></div></div><div class="scan-grid" aria-hidden="true"></div>
<header class="site-header"><a class="brand" href="index.html" aria-label="TechCell, página inicial">{logo}<span>Tech<span>Cell</span><small>Assistência Técnica</small></span></a><nav id="nav" class="main-nav" aria-label="Navegação principal">{nav}</nav><div class="header-tools"><button class="icon-button" data-search-open aria-label="Buscar no site">{icon('search')}</button><button class="icon-button notifications-button" data-notifications aria-label="Informações de atendimento">{icon('bell')}<i></i></button></div>{btn('Fale no WhatsApp','contato.html','primary header-contact','whatsapp')}<button class="menu-button icon-button" aria-label="Abrir menu" aria-controls="nav" aria-expanded="false"><span></span><span></span><span></span></button></header>
<aside class="side-nav" aria-label="Atalhos">{side}</aside><main id="main" class="{'home-main' if slug=='index' else 'page-main'}">{content()}</main>
<footer class="site-footer"><span>{icon('clock')}<strong>Atendimento Hoje:</strong> 08h às 19h</span><a href="contato.html">{icon('pin')}<strong>Localização:</strong> Piúma – ES</a><span>{icon('card')}<strong>Aceitamos:</strong> Pix · Cartão · Parcelamento</span><button class="motion-toggle" aria-label="Pausar animações" aria-pressed="false">Pausar animações</button></footer>
<dialog id="search-dialog" class="modal search-modal" aria-labelledby="search-title"><button class="close-modal icon-button" aria-label="Fechar busca">{icon('close')}</button><p class="eyebrow">ENCONTRE SUA PRÓXIMA CONEXÃO</p><h2 id="search-title">O que você procura?</h2><label class="search-field">{icon('search')}<input type="search" id="global-search" placeholder="Serviços, dúvidas, contato…" autocomplete="off" aria-label="Buscar no site"></label><div id="search-results" aria-live="polite"></div></dialog>
<dialog id="service-dialog" class="modal" aria-labelledby="service-title"><button class="close-modal icon-button" aria-label="Fechar detalhes">{icon('close')}</button><span class="large-holo" id="service-icon"></span><p class="eyebrow">SOLUÇÃO TECHCELL</p><h2 id="service-title"></h2><p id="service-description"></p><div class="service-qualities"><span>{icon('search')}Avaliação individual</span><span>{icon('shield')}Orientação especializada</span></div><a class="button primary" id="service-contact">Solicitar diagnóstico {icon('arrow')}</a></dialog>
<div class="toast" id="toast" role="status" hidden></div><noscript><div class="noscript-message">Ative o JavaScript para usar os efeitos e as interações. As páginas continuam disponíveis pelos links de navegação.</div></noscript></body></html>'''
 (ROOT/(slug+'.html')).write_text(html)
print(f'{len(PAGES)} páginas geradas.')
